using UnityEngine; namespace MyLumo { public class LumoAnimatorBridge:MonoBehaviour { public Animator animator; static readonly int Speed=Animator.StringToHash("Speed"),Eat=Animator.StringToHash("Eat"),Sleep=Animator.StringToHash("Sleep"),Dance=Animator.StringToHash("Dance"),Dress=Animator.StringToHash("Dress"),Guitar=Animator.StringToHash("Guitar"),Pet=Animator.StringToHash("Pet"),Build=Animator.StringToHash("Build"); public void SetMoveSpeed(float s){if(animator)animator.SetFloat(Speed,s);} public void Trigger(LumoActionType a){if(!animator)return; switch(a){case LumoActionType.Eat:animator.SetTrigger(Eat);break;case LumoActionType.Sleep:animator.SetTrigger(Sleep);break;case LumoActionType.Dance:animator.SetTrigger(Dance);break;case LumoActionType.Dress:animator.SetTrigger(Dress);break;case LumoActionType.PlayGuitar:animator.SetTrigger(Guitar);break;case LumoActionType.PetAnimal:animator.SetTrigger(Pet);break;case LumoActionType.Build:animator.SetTrigger(Build);break;}} } }
